-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it; null: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2);
-- The role a user name has on a sheet; a name with no row is a clerk.
CREATE TABLE user_role (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role VARCHAR(20) NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's floor: a claim's live due is at least it.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) NOT NULL DEFAULT 1.00;
-- The sheet's terms: a claim is due by its date plus this many days.
ALTER TABLE sheet ADD COLUMN terms INT NOT NULL DEFAULT 14;
=== Settings.java
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.List;

/**
 * A sheet's settings: its clerk limit (null: no limit), its floor (a claim's live due is at least it), its terms
 * (a claim is due by its date plus this many days) and the
 * roles given to user names (any other name is a clerk).
 */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, List<UserRole> roles) {

    /** The role of the user name: the one given to it, else clerk. */
    public Role roleOf(String user) {
        return roles.stream().filter((r) -> r.user().equals(user)).map(UserRole::role).findFirst().orElse(Role.CLERK);
    }

    /** Whether the user may settle a claim with this due (null: n/a, within any limit). */
    public boolean maySettle(String user, BigDecimal due) {
        return roleOf(user) == Role.STEWARD || clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
