-- The role a user name has on a sheet; a name with no row is a clerk.
CREATE TABLE user_role (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role VARCHAR(20) NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's floor: a claim's live due is at least it.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) NOT NULL DEFAULT 1.00;
-- The sheet's terms: a claim is due by its date plus this many days.
ALTER TABLE sheet ADD COLUMN terms INT NOT NULL DEFAULT 14;
