package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one.
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, Integer number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue) {

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, Integer nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue);
    }

    /** Whether the claim counts toward the totals: only OPEN and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when its person is held or not: a held person's open claims do not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status == ClaimStatus.OPEN && !held);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to, else its amount at the given live rate (null: none), at least the sheet's floor.
     */
    public BigDecimal figure(BigDecimal liveRate, BigDecimal floor) {
        if (due != null) {
            return due;
        }
        return stated ? statedDue : due(amount, liveRate, floor);
    }

    /** An amount times a percent rate, divided by 100, rounded half to even to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** A live due: {@link #due(BigDecimal, BigDecimal)}, raised to the floor; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, BigDecimal floor) {
        BigDecimal due = due(amount, rate);
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(Integer number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
 * Opening gives the claim the sheet's next number; a voided claim keeps its number (it is never reused).
 * Opening records the user who opened it; that user cannot settle it (four eyes).
 * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to the sheet's floor — or, when a statement
 * bound the claim, at the figure it was bound to; with no figure it stays live.
 */
public class ApplyClaimAction {
    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings,
            Out<ClaimAction> applied, Out<ClaimNumber> number, Out<Claim> updated) throws InvalidClaimException {
        ClaimAction found = ClaimAction.of(action);
        if (found == null) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
        if (!found.allowedFrom(claim.status())) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
        }
        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
        }
        Integer next = switch (found) {
            case OPEN -> sheets.nextClaimNumber(claim.sheetId());
            default -> claim.number();
        };
        applied.set(found);
        number.set(new ClaimNumber(next));
        BigDecimal due = found == ClaimAction.SETTLE ? settledDue(claim, people, rates, settings) : claim.due();
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
    }

    private static BigDecimal settledDue(Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        BigDecimal rate = person == null ? null
                : Rate.inForce(rates.findAll(claim.sheetId()), person.grade(), claim.date());
        return Claim.due(claim.amount(), rate, settings.floor(claim.sheetId()));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: records their due-total now, binds each of their claims that counts to the
 * figure it has now (a live one raised to the sheet's floor), and unbinds (live again) each that does not. The due-total is their counting claims'
 * figures added up; n/a when their grade has no rate on the sheet's today and no counting claim keeps a figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Out<Statement> statement, Out<Person> updated) {
        LocalDate today = sheets.today(person.sheetId());
        List<Rate> sheetRates = rates.findAll(person.sheetId());
        BigDecimal floor = settings.floor(person.sheetId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim claim : claims.findForPerson(person.sheetId(), person.id())) {
            if (!person.counts(claim)) {
                claims.bindStatement(claim, false, null);
                continue;
            }
            boolean fixed = claim.due() != null || (claim.stated() && claim.statedDue() != null);
            BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.grade(), claim.date()), floor);
            claims.bindStatement(claim, true, figure);
            counted++;
            kept |= fixed;
            if (figure != null) {
                total = total.add(figure);
            }
        }
        String dueTotal = Rate.inForce(sheetRates, person.grade(), today) == null && !kept ? "n/a"
                : total.setScale(2).toPlainString();
        statement.set(new Statement(person.name(), dueTotal, counted));
        updated.set(people.recordStatement(person, dueTotal, today));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Closes the period, fixing its due-total as it stands now: the figures of the counting claims dated in it,
 * added up (n/a skipped). Refused (400) when it is already closed.
 */
public class ClosePeriod {
    public void close(@Val Period period, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, Out<Period> closed) throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
        }
        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, Function.identity()));
        List<Rate> sheetRates = rates.findAll(period.sheetId());
        BigDecimal floor = settings.floor(period.sheetId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findAll(period.sheetId())) {
            Person person = byId.get(claim.personId());
            if (person == null || !person.counts(claim) || !period.contains(claim.date())) {
                continue;
            }
            BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.grade(), claim.date()), floor);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        closed.set(period.close(total));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' figures (live ones raised to the sheet's floor) added up, n/a when their grade has no rate on the sheet's
 * today and no counting claim keeps a figure. The sheet's totals add these up, skipping n/a.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.due() != null || (claim.stated() && claim.statedDue() != null);
                BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.grade(), claim.date()), floor);
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due)));
        }
        return new Rollup(figures, show(claimedTotal), show(dueTotal));
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
-- A person's statement records their due-total at that moment and binds each of their counting
-- claims to the figure it has then. The person keeps how many statements were taken, the last one's
-- due-total ('n/a' when it had none) and the sheet's today when it was taken.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A stated claim shows and totals its bound figure (stated_due; null: n/a) until its person's next
-- statement rebinds it, or unbinds it (live again) when it no longer counts.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(25, 2);

